parameters.jsCode:
// Format SW1 response for Router
const items = $input.all();
const aiOutput = items[0].json.output || items[0].json;
const inputData = $('When Executed by Another Workflow').first().json;

// Parse AI output if it's a string (handle markdown code blocks)
let parsedOutput = aiOutput;
if (typeof aiOutput === 'string') {
  // Remove markdown code blocks if present
  const cleaned = aiOutput.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  try {
    parsedOutput = JSON.parse(cleaned);
  } catch (e) {
    // If parsing fails, treat as plain text
    parsedOutput = { summary: aiOutput };
  }
}

// If AI returned structured response, use it
if (parsedOutput.workflow === 'SW1') {
  return [{
    json: parsedOutput
  }];
}

// Otherwise, build structured response
let response = {
  workflow: 'SW1',
  operation: 'unknown',
  success: true,
  data: null,
  summary: '',
  error: null
};

// Merge parsed output
if (typeof parsedOutput === 'object') {
  response = { ...response, ...parsedOutput };
} else {
  response.summary = String(parsedOutput);
}

// Infer operation type from input data
if (inputData.ticket_id) {
  response.operation = 'get_ticket';
} else if (inputData.intent && inputData.intent.includes('workload')) {
  response.operation = 'analytics';
} else if (inputData.customer_email || inputData.query) {
  response.operation = 'search';
} else {
  response.operation = 'list_tickets';
}

return [{
  json: response
}];

// Log API call to Supabase
const items = $input.all();
const inputData = $('When Executed by Another Workflow').first().json;
const response = items[0].json;

// Build log entry
const logEntry = {
  workflow_id: 'SW1',
  run_id: $execution.id,
  node_name: 'SW1_AI_Agent',
  direction: 'response',
  method: response.operation || 'read',
  url: inputData.ticket_id 
    ? `https://ironsidecomputers.gorgias.com/api/tickets/${inputData.ticket_id}`
    : 'https://ironsidecomputers.gorgias.com/api/tickets',
  status_code: response.success ? 200 : 500,
  request_body: JSON.stringify({
    ticket_id: inputData.ticket_id,
    filters: inputData.filters,
    intent: inputData.intent
  }),
  response_body: JSON.stringify(response.data || response.summary),
  error_message: response.error || null,
  actor_user: inputData.user || null,
  channel: inputData.channel || null,
  thread_ts: inputData.thread_ts || null,
  ticket_id: inputData.ticket_id || null,
  tags: [],
  duration_ms: null,
  extra: JSON.stringify({
    operation: response.operation,
    intent: inputData.intent
  })
};

return [{
  json: logEntry
}];

// SW1 Error Handler - Catch and format errors
const error = $input.first().json.error || $input.first().json;
const inputData = $('When Executed by Another Workflow').first().json;

let errorMessage = 'An error occurred while reading ticket data.';
let errorDetails = '';
let statusCode = 500;

// Extract useful error info
if (error.message) {
  errorDetails = error.message;
} else if (typeof error === 'string') {
  errorDetails = error;
} else if (error.response?.data?.message) {
  errorDetails = error.response.data.message;
} else if (error.httpCode) {
  statusCode = error.httpCode;
  errorDetails = error.message || 'HTTP error occurred';
}

// Determine user-friendly message based on error type
if (errorDetails.includes('404') || errorDetails.includes('not found')) {
  errorMessage = '❌ Ticket not found. Please check the ticket number and try again.';
  statusCode = 404;
} else if (errorDetails.includes('401') || errorDetails.includes('unauthorized')) {
  errorMessage = '🔒 Authentication failed. Please contact your administrator.';
  statusCode = 401;
} else if (errorDetails.includes('403') || errorDetails.includes('forbidden')) {
  errorMessage = '⛔ Access denied. You may not have permission for this operation.';
  statusCode = 403;
} else if (errorDetails.includes('429') || errorDetails.includes('rate limit')) {
  errorMessage = '⏱️ Too many requests. Please wait a moment and try again.';
  statusCode = 429;
} else if (errorDetails.includes('500') || errorDetails.includes('internal server')) {
  errorMessage = '🔥 Gorgias server error. Please try again in a few minutes.';
  statusCode = 500;
} else if (errorDetails.includes('timeout')) {
  errorMessage = '⏰ Request timed out. Please try again.';
  statusCode = 408;
} else if (errorDetails.includes('ECONNREFUSED') || errorDetails.includes('network')) {
  errorMessage = '🌐 Network error. Please check your connection and try again.';
  statusCode = 503;
}

// Build error response for Router
const errorResponse = {
  workflow: 'SW1',
  operation: 'error',
  success: false,
  data: null,
  summary: errorMessage,
  error: errorDetails
};

// Build Supabase log entry
const logEntry = {
  workflow_id: 'SW1',
  run_id: $execution.id,
  node_name: 'SW1_Error_Handler',
  direction: 'error',
  method: 'read_error',
  url: inputData.ticket_id 
    ? `https://ironsidecomputers.gorgias.com/api/tickets/${inputData.ticket_id}`
    : 'https://ironsidecomputers.gorgias.com/api/tickets',
  status_code: statusCode,
  request_body: JSON.stringify({
    ticket_id: inputData.ticket_id,
    filters: inputData.filters,
    query: inputData.query
  }),
  response_body: null,
  error_message: errorDetails,
  actor_user: inputData.user || null,
  channel: inputData.channel || null,
  thread_ts: inputData.thread_ts || null,
  ticket_id: inputData.ticket_id || null,
  tags: [],
  duration_ms: null,
  extra: JSON.stringify({
    error_type: error.name || 'UnknownError',
    error_code: statusCode,
    original_error: JSON.stringify(error).substring(0, 500)
  })
};

return [{
  json: {
    errorResponse: errorResponse,
    logEntry: logEntry
  }
}];
